<?php defined( 'ABSPATH' ) || exit; $panel_id = isset( $args['panel_id'] ) ? sanitize_html_class( $args['panel_id'] ) : 'blog-menu'; $trigger_id = isset( $args['trigger_id'] ) ? sanitize_html_class( $args['trigger_id'] ) : ''; $overview_url = isset( $args['overview_url'] ) ? $args['overview_url'] : home_url( '/blog/' ); $posts = get_posts( array( 'post_type' => 'post', 'posts_per_page' => 4, 'post_status' => 'publish', 'ignore_sticky_posts' => true ) ); ?><div id="<?php echo esc_attr( $panel_id ); ?>" class="nytt01-mega-menu nytt01-mega-menu--blog" aria-labelledby="<?php echo esc_attr( $trigger_id ); ?>" data-menu-dropdown="blog" hidden><div class="nytt01-mega-menu__blog-header"><div><p class="nytt01-eyebrow"><?php esc_html_e( 'From the blog', 'nolan-young-theme-template-01' ); ?></p><h2><?php esc_html_e( 'Latest insights', 'nolan-young-theme-template-01' ); ?></h2></div><a href="<?php echo esc_url( $overview_url ); ?>"><?php esc_html_e( 'View all posts', 'nolan-young-theme-template-01' ); ?></a></div><div class="nytt01-card-grid"><?php foreach ( $posts as $post ) : setup_postdata( $post ); ?><article class="nytt01-mega-blog-card"><a href="<?php the_permalink(); ?>"><?php if ( has_post_thumbnail() ) the_post_thumbnail( 'medium_large' ); ?></a><p class="nytt01-eyebrow"><?php echo esc_html( get_the_category_list( ', ' ) ); ?></p><h3><a href="<?php the_permalink(); ?>"><?php the_title(); ?></a></h3><p><?php echo esc_html( wp_trim_words( get_the_excerpt(), 18 ) ); ?></p></article><?php endforeach; wp_reset_postdata(); ?></div></div>
